#include <cstdio>
#include <cstdlib>

class FileHandle {
public:
    FileHandle(const char* path, const char* mode)
        : file_(std::fopen(path, mode)) {
        if (file_ == nullptr) {
            std::abort();
        }
    }

    ~FileHandle() {
        std::fclose(file_);
    }

    FileHandle(const FileHandle&) = delete;
    FileHandle& operator=(const FileHandle&) = delete;

    std::FILE* get() const {
        return file_;
    }

private:
    std::FILE* file_;
};

bool write_report(const char* path, const char* text) {
    FileHandle output{path, "w"};

    if (text == nullptr) {
        return false;  // output closes
    }
    if (std::fputs(text, output.get()) < 0) {
        return false;  // output closes
    }
    return true;       // output closes
}

#include <string>

class Session {
public:
    Session(int id, std::string& log, const std::string& endpoint)
        // A const member can only ever receive a value here: there is no
        // assignment that could set it afterwards.
        : id_(id),
        // A reference must bind during initialization and can never be
        // reseated, so the body could not have established it either.
          log_(log),
        // endpoint_ *could* have been assigned in the body — that would just
        // default-construct it first and then assign, doing two operations
        // (and possibly two allocations) where this does one.
          endpoint_(endpoint) {}

    const std::string& endpoint() const { return endpoint_; }

private:
    const int id_;
    std::string& log_;
    std::string endpoint_;
};

