#include <cstddef>
#include <vector>

class Packet {
public:
    // Members are initialized in *declaration* order, whatever order the
    // initializer list uses. In the original, buffer_ was declared first and
    // so read size_ before size_ had been initialized. Reordering only the
    // initializer list would have changed nothing; the declarations are the
    // dependency order. Compilers flag the mismatch with -Wreorder.
    explicit Packet(int size)
        : size_(size), buffer_(static_cast<std::size_t>(size_)) {}

    std::size_t capacity() const { return buffer_.size(); }

private:
    int size_;
    std::vector<int> buffer_;
};

#include <iostream>
#include <string>

std::string make_name() {
    return "EURUSD";
}

const std::string& pass_through(const std::string& value) {
    return value;
}

void correct() {
    // Direct binding of a temporary to a local const reference: the
    // temporary's lifetime is extended to the end of this scope.
    const std::string& symbol = make_name();
    std::cout << symbol << '\n';
}  // temporary destroyed here

void dangling() {
    // The temporary binds to pass_through's *parameter*, which keeps it alive
    // for the duration of the call and no longer. Returning that parameter's
    // reference grants no second extension, so the temporary is destroyed at
    // the semicolon below.
    const std::string& symbol = pass_through(make_name());
    std::cout << symbol << '\n';  // UB: symbol dangles
}

