#include <cstdio>

struct Logger {
    Logger() { /* acquire logging destination */ }

    void write(const char* message) const { std::puts(message); }
};

// Before: `Logger global_logger;` in one translation unit and
// `Config global_config;` in another. Within one translation unit dynamic
// initialization follows definition order, but *across* translation units the
// relative order is unspecified, so Config's constructor could touch storage
// where no Logger object had begun its lifetime yet.
//
// After: a function-local static is initialized the first time control reaches
// its declaration, so the Logger is fully constructed before logger() returns,
// on every path that could ever use it.
Logger& logger() {
    static Logger instance;
    return instance;
}

struct Config {
    Config() { logger().write("loading config"); }
};

Config global_config;

struct Quote {
    double bid;
    double ask;
    int venue;
};

void initialization_forms() {
    // Value-initialization: every member is zero.
    Quote zeroed{};

    // Positional aggregate initialization: members are initialized in
    // declaration order. Nothing stops bid and ask being transposed here --
    // both are double, so the compiler cannot help.
    Quote positional{99.50, 99.70, 3};

    // Designated initializers (C++20) name the members and must follow
    // declaration order. This is the form that survives a code review.
    Quote named{.bid = 99.50, .ask = 99.70, .venue = 3};

    // Ill-formed: braces reject narrowing, and 3.5 does not convert to int
    // without losing value. With parentheses this would silently store 3.
    // Quote narrowed{99.50, 99.70, 3.5};

    (void)zeroed;
    (void)positional;
    (void)named;
}
